import random
import string
from typing import List
import struct

# Note: Do not embed literal null bytes in the source. Any NULs are produced at runtime.

# Protobuf-style helpers for crafting plausible SentencePiece ModelProto blobs

def _varint(n: int) -> bytes:
    out = bytearray()
    n &= (1 << 64) - 1
    while True:
        b = n & 0x7F
        n >>= 7
        if n:
            out.append(0x80 | b)
        else:
            out.append(b)
            break
    return bytes(out)

def _key(field_number: int, wire_type: int) -> bytes:
    return _varint((field_number << 3) | wire_type)

def _len_delim(b: bytes) -> bytes:
    return _varint(len(b)) + b

# SentencePiece piece message: 1: piece (len-delim), 2: score (32-bit float), 3: type (varint)

def _sp_piece(piece_str: str, score: float = 0.0, ptype: int = 0) -> bytes:
    msg = bytearray()
    piece_bytes = piece_str.encode('utf-8', errors='ignore')
    msg += _key(1, 2) + _len_delim(piece_bytes)
    msg += _key(2, 5) + struct.pack('<f', score)
    msg += _key(3, 0) + _varint(ptype)
    return bytes(msg)

# Minimal NormalizerSpec: name field only (field 1)

def _normalizer_spec(name: str) -> bytes:
    msg = bytearray()
    msg += _key(1, 2) + _len_delim(name.encode('utf-8'))
    return bytes(msg)

# Minimal ModelProto: 1 model_type (varint), 2 repeated piece (len-delim), 4 normalizer_spec (len-delim)

def _model_proto_blob(pieces: List[bytes], model_type: int = 0, include_norm: bool = True) -> bytes:
    msg = bytearray()
    msg += _key(1, 0) + _varint(model_type)
    for p in pieces:
        msg += _key(2, 2) + _len_delim(p)
    if include_norm:
        norm = _normalizer_spec('nmt_nfkc_cf')
        msg += _key(4, 2) + _len_delim(norm)
    return bytes(msg)

# Generators for different interesting string/blobs

def _ascii_edge_patterns(rng: random.Random) -> bytes:
    # Avoid embedding actual null chars in source; generate only at runtime if needed elsewhere
    patterns = [
        "", " ", "\t", "\n", "\r\n", "A" * rng.randint(1, 64),
        "-–—_", ".,;:!?",
        string.printable,
    ]
    s = rng.choice(patterns)
    return s.encode('utf-8')


def _utf8_rich(rng: random.Random, length: int) -> bytes:
    chunks = [
        "こんにちは", "Привет", "مرحبا", "γειά", "हैलो", "สวัสดี", "你好", "안녕하세요",
        "naïve", "coöperate", "mañana", "façade",
        "Zalgo: ẕ͉͍̲͎͍̙a͓̪̻̟̤l̡̥g̻o̠̰",
        "emoji: 😀😇🤖🧪",
    ]
    s = rng.choice(chunks)
    extra = ''.join(chr(rng.randint(0x00A0, 0x0FFF)) for _ in range(max(0, length - len(s))))
    out = (s + extra)[:length]
    return out.encode('utf-8', errors='ignore')


def _with_controls(rng: random.Random, total_len: int) -> bytes:
    data = bytearray()
    base = "error: something went wrong"
    data.extend(base.encode('ascii'))
    # Insert control bytes (non-NUL)
    control_bytes = [0x01, 0x02, 0x07, 0x08, 0x09, 0x0A, 0x0D, 0x1B]
    for _ in range(rng.randint(1, 16)):
        pos = rng.randint(0, len(data))
        b = rng.choice(control_bytes)
        data[pos:pos] = bytes([b])
        if len(data) >= total_len:
            break
    while len(data) < total_len:
        data.append(rng.randrange(1, 256))  # avoid NUL (0)
    return bytes(data[:total_len])


