    types = {"<unk>": 1, "<s>": 2, "</s>": 2, "<pad>": 4}
    for _ in range(num_p):
        piece = rng.choice(vocab_candidates)
        ptype = types.get(piece, 0)
        score = rng.uniform(-10.0, 0.0)
        pieces.append(_sp_piece(piece, score, ptype))
    blob = _model_proto_blob(pieces, model_type=mtype, include_norm=True)
    return blob


def _mixed_blob(rng: random.Random, max_len: int) -> bytes:
    proto = _proto_like_model(rng)
    suffix_text = "\n# comment: "
    suffix = suffix_text.encode('utf-8') + _utf8_rich(rng, rng.randint(5, 40))
    blob = proto + suffix
    return blob[:max_len]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    choice = rng.random()
    max_len = 4096

    if choice < 0.25:
        return _ascii_edge_patterns(rng)[:max_len]
    elif choice < 0.5:
        length = rng.randint(1, min(512, max_len))
        return _utf8_rich(rng, length)
    elif choice < 0.75:
        length = rng.randint(1, min(1024, max_len))
        return _with_controls(rng, length)
    else:
        if rng.random() < 0.7:
            return _proto_like_model(rng)[:max_len]
        else:
            return _mixed_blob(rng, max_len)
